import { StudioProApi } from "@mendix/extensions-api";
import { Model, Provider } from "../../types/model/model";
import { MxCloudGenAIModelFields } from "../../types/model/mxCloudGenAIModel";
import { createNewMxCloudGenAIModelFields } from "../../utils/modelUtils"
import { createStudioProLogger } from "../../config/logger";

export const updateModelDocument = async (studioPro: StudioProApi, model: Model, documentId: string) => {
    const logger = createStudioProLogger(studioPro);
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, model);
    } catch (error) {
        logger.error("Failed to save model document:", error);
        studioPro.ui.notifications.show({
            title: "Failed to save model document.",
            message: (error as Error).message
        });
    }
};


export const handleProviderChange = (studioPro: StudioProApi, model: Model, setModel: React.Dispatch<React.SetStateAction<Model>>, documentId: string, newProvider: Provider) => async () => {

    // Don't reinitialize if provider fields are already of the correct type
    if (model.provider === newProvider && 'key' in model.providerFields) {
        return;
    }

    // Initialize provider-specific fields when provider is selected
    if (newProvider === "MxCloudGenAI") {

        const newProviderFields: MxCloudGenAIModelFields = createNewMxCloudGenAIModelFields();

        const updatedModel = { ...model, provider: newProvider, providerFields: newProviderFields };
        setModel(updatedModel);
        updateModelDocument(studioPro, updatedModel, documentId);
    }
};