import React, { useState } from 'react';
import { DivFlexColumn, DivFlexRow, StyledLabel } from './elements/formelements';
import { Button } from "@mendix/ide-ui-components/button/Button";

interface ButtonDisabledDuringActionProps {
    onPress?: () => void | Promise<void>;
    buttonCaption: string;
}

const ButtonDisabledDuringAction: React.FC<ButtonDisabledDuringActionProps> = ({
    onPress,
    buttonCaption
}) => {
    const [isLoading, setIsLoading] = useState(false);

    const handlePress = async () => {
        if (!onPress || isLoading ) return;
        
        setIsLoading(true);
        try {
            await onPress();
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <DivFlexRow>
            <DivFlexColumn>
                <Button
                    onPress={handlePress}
                    isDisabled={isLoading}
                >{buttonCaption}</Button>
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default ButtonDisabledDuringAction;